### templates.ts
```typescript
import Handlebars from 'handlebars';
import fs from 'fs';
import path from 'path';

export class TemplateEngine {
  private layouts: Record<string, HandlebarsTemplateDelegate> = {};
  private templates: Record<string, HandlebarsTemplateDelegate> = {};

  constructor(templateDir: string) {
    // Load partials
    const partialsDir = path.join(templateDir, 'partials');
    if (fs.existsSync(partialsDir)) {
      this.loadPartials(partialsDir);
    }

    // Load layouts
    const layoutsDir = path.join(templateDir, 'layouts');
    if (fs.existsSync(layoutsDir)) {
      for (const file of fs.readdirSync(layoutsDir)) {
        if (file.endsWith('.hbs') || file.endsWith('.handlebars')) {
          const name = path.basename(file, path.extname(file));
          const source = fs.readFileSync(path.join(layoutsDir, file), 'utf-8');
          this.layouts[name] = Handlebars.compile(source);
        }
      }
    }

    // Load templates
    for (const file of fs.readdirSync(templateDir)) {
      if (file.endsWith('.hbs') || file.endsWith('.handlebars')) {
        const name = path.basename(file, path.extname(file));
        const source = fs.readFileSync(path.join(templateDir, file), 'utf-8');
        this.templates[name] = Handlebars.compile(source);
      }
    }
  }

  private loadPartials(dir: string): void {
    for (const file of fs.readdirSync(dir)) {
      if (file.endsWith('.hbs') || file.endsWith('.handlebars')) {
        const name = path.basename(file, path.extname(file));
        const source = fs.readFileSync(path.join(dir, file), 'utf-8');
        Handlebars.registerPartial(name, source);
      }
    }
  }

  render(templateName: string, data: Record<string, unknown>, layoutName: string = 'default'): string {
    const template = this.templates[templateName];
    if (!template) {
      throw new Error(`Template not found: ${templateName}`);
    }
    let content = template(data);

    // Wrap in layout if available
    const layout = this.layouts[layoutName];
    if (layout) {
      content = layout({ ...data, body: content });
    }

    return content;
  }
}
```

