import { PostData } from './types';

export function buildTagIndex(posts: PostData[]): Record<string, PostData[]> {
  const tags: Record<string, PostData[]> = {};

  for (const post of posts) {
    if (post.draft) continue;
    for (const tag of post.tags) {
      if (!tags[tag]) {
        tags[tag] = [];
      }
      tags[tag].push(post);
    }
  }

  return tags;
}

export function getAllTags(posts: PostData[]): string[] {
  const tags = buildTagIndex(posts);
  return Object.keys(tags).sort();
}
