import { Feed } from 'feed';
import { PostData, SiteConfig } from './types';

export function generateRSS(posts: PostData[], site: SiteConfig): string {
  const feed = new Feed({
    title: site.title,
    description: site.description,
    id: site.url,
    link: site.url,
    updated: posts.length > 0 ? new Date(posts[0].date) : new Date(),
    generator: 'SSG',
    feedLinks: {
      rss2: `${site.url}/feed.xml`,
    },
  });

  for (const post of posts) {
    if (post.draft) continue;
    feed.addItem({
      title: post.title,
      id: post.url,
      link: `${site.url}/${post.url}`,
      date: new Date(post.date),
      content: post.content,
    });
  }

  return feed.rss2();
}
